{{-- The Show details panel icon of a list (design 29d): sits in the last header cell of the table while the panel is off; the panel's own » button hides it. --}}
<button type="button" wire:click="toggleDetails" class="ls-hide" title="Show details panel" aria-label="Show details panel"><svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="3" y="4" width="18" height="16" rx="2"/><line x1="14.5" y1="4" x2="14.5" y2="20"/></svg></button>
